"content/notices/6055.html": `
<div class="md-body">
<p class="md-p">ISO 인증심사원 분야별 필기시험(2024. 10. 25 시행) 장소 안내</p>
<p class="md-p">ISO 인증심사원 분야별 필기시험(2024. 10. 25 시행) 장소를 아래와 같이 안내합니다.</p>
<p class="md-p">□ 분야별 필기시험 응시 내용</p>
<p class="md-p">자격 분야  회차  표준
품질경영시스템(QMS, ISO 9001)  제145회  KS Q ISO 9001:2015
환경경영시스템(EMS, ISO 14001)  제101회  KS Q ISO 14001:2015
안전보건경영시스템(OHSMS, ISO 45001)  제85회  KS Q ISO 45001:2018</p>
<p class="md-p">□ 시험일시 : 2024년 10월 25일(금) 14:00 ~ 16:00 (2시간)
※ 당일 오후 1시 30분까지 시험장 입실 완료</p>
<p class="md-p">□ 시험장소 : 가산 BYC 하이시티 C동 302호
- 주 소 : 서울특별시 금천구 가산디지털1로 131
- 교통편 : 지하철 가산디지털단지역 1, 7호선 7번 출구방향 200미터</p>
<p class="md-p">□ 응시자 명단
- 제145회 품질경영시스템(QMS, ISO 9001)</p>
<p class="md-p">연번  수험번호  성명
1  Q2410002  진 *호
2  Q2410005  이 *현</p>
<p class="md-p">- 제101회 환경경영시스템(EMS, ISO 14001)</p>
<p class="md-p">연번  수험번호  성명
1  E2410001  유 *재</p>
<p class="md-p">- 제85회 안전보건경영시스템(OHSMS, ISO 45001)</p>
<p class="md-p">연번  수험번호  성명
1  O2410001  여 *민
2  O2410003  권 *상
3  O2410004  박 *준</p>
<p class="md-p">□ 응시자 유의사항
1. 답안 작성 관련 안내
가. 흑색 볼펜 또는 유성펜 등 지워지지 않는 검정색 필기구 사용
※ 연필로 답안 작성 시 무효처리
나. 답안 수정시 수정 테이프(수정액)를 사용하거나 두 줄로 횡선을 긋고, 새로운 답안을 작성하여 감독자의 날인을 받아야 함
다. 시험문제 중에는 제시된 문항수를 선택하여 작성하는 선택형 문제가 있음
1) 제시된 문항수 이상을 시험지에 기술시 작성된 번호 순서대로 채점대상이 됨
2) 선택하지 않은 문제는 문제번호에 X를 크게 표시 후 “선택안함” 이라고 자필로 표기해야 함
2. 주차 불가, 대중교통수단 이용 요망
※ 본 건물 주차장 이용시, 주차 요금은 개인 부담
3. 응시자 지참물 : 개인 손목시계, 신분증(주민등록증, 운전면허증, 여권, 공무원증 등)
※ 신분증 미소지시 응시 불가
4. 시험점수와 답안지는 미공개를 원칙으로 함
5. 질문이 있는 경우는 거수 (단, 문제 자체에 대한 질문은 응답하지 않음)
6. 배부된 KS 표준 낙서 금지 (회수되어 재사용 됨)
7. 시험시행 후 60분 후부터 퇴실 가능하며, 퇴실 후 재입실 불가
8. 시험 결시시 시험횟수가 1회 차감되며, 차기 시험 신청 시 응시료를 납부하여야 함
9. 시험 부정행위자는 우리원에서 주관하는 모든 시험에 3년간 시험을 응시 불가</p>
<p class="md-p">□ 합격자 발표 : : 2024년 11월 08일 (금) 10:00
- 개인별 문자 메시지 및 우리원 홈페이지 【필기시험 &gt; 합격자 발표】를 통하여 합격자 결과 발표</p>
</div>
`,
