"content/notices/6059.html": `
<div class="md-body">
<p class="md-p">안녕하세요. 한국심사자격인증원입니다.</p>
<p class="md-p">ISO 9001 APG(심사수행그룹)에서 ISO 9001에서의 기후변화 사항 심사를 신규 발행함에 따라 KAB에서 이를 번역하여 제공하오니, 참고하시기 바랍니다
또한, ISO 9001 APG 및 ISO 14001 APG의 기존 발행문서 전체의 국문 번역 자료도 첨부에서 보실 수 있습니다.</p>
<p class="md-p">ㅇ 국문 번역자료 : ISO 9001 APG 문서 22종 + ISO 14001 APG 문서 6종
ISO 9001 APG 문서  ISO 14001 APG 문서
1. 적격성  1. “의사소통하는 정보”의 심사 및 인증
2. 상황  2. 외부 공급자 심사
3. 고객 의사소통  3. 전과정 관점 심사
4. 고객 불만  4. 개선
5. 고객 피드백  5. 리스크 및 기회
6. 설계와 개발 프로세스  6. 환경경영시스템 심사원의 지식 및 스킬의 예
7. 외부 공급자
8. 개선
9. 내부심사
10. 내부 의사소통
11. 측정 소급성
12. 모니터링 및 측정 자원
13. 조직의 지식
14. 방침, 목표 및 경영검토
15. 프로세스
16. 자원
17. 리스크기반 사고
18. 범위 및 적용가능성
19. 서비스 조직
20. 법적 및 규제적 요구사항
21. 최고경영자/최고경영진
22. ISO 9001에서의 기후변화 사항 심사
[출처] 한국인정지원 센터 &gt; 스마트인정시스템 &gt; 공지사항 &gt; 12번 APG(심사수행그룹) 문서 국문 번역자료 제공 게시물</p>
<p class="md-p">감사합니다.</p>
</div>
`,
"content/notices/6060.html": `
<div class="md-body">
<p class="md-p">[모듈2] OHSMS(하반기) 심사경력인정 특별과정 장소 안내</p>
<p class="md-p">.
안녕하세요 한국심사자격인증원입니다  .
2024. 11. 9(토) ~ 11. 30(토)에 개최하는 [모듈2] OHSMS(하반기) 심사경력인정 특별과정을 아래와 같이 안내합니다.</p>
<p class="md-p">1) 교육기간 : 2024년 11월 9일(토) ~ 11월 30일(토), 09:00 ~ 18:00 (주말/총7일)
2) 교육장소 : 한국심사자격인증원 강의실(첨부 참조)
- 주소 : 서울특별시 금천구 가산디지털1로 168, B동 1102호(가산동, 우림라이온스밸리)
- 교통편 : 가산디지털단지역 7번출구에서 도보 1분거리(약 28m)
3) 주차안내
- 우림라이온스밸리 B동에 주차 가능하며, [성함/차량번호/주차신청일자]를 말씀주시면 등록 가능함
·주차비용 : 15,000원(1일) (계좌이체만 가능, 카드결제불가)
·입금 계좌 : 기업은행 478-002057-01-041 (예금주 : 한국심사자격인증원)</p>
<p class="md-p">기타 문의사항 있으신 경우  , 02-2026-0153으로 연락 바랍니다.
감사합니다  .</p>
</div>
`,
"content/notices/6061.html": `
<div class="md-body">
<p class="md-p">ISO 인증심사원 분야별 필기시험(2024. 11. 29 시행) 유의사항 안내</p>
<p class="md-p">다음 분야의 인증심사원 필기시험이 2024년 11월 29일 (금) 14:00에 실시됩니다.</p>
<p class="md-p">ㅇ 제146회 품질경영시스템 (KS Q ISO 9001:2015)
ㅇ 제102회 환경경영시스템 (KS I ISO 14001:2015)
ㅇ 제86회 안전보건경영시스템 (KS Q ISO 45001:2018)
ㅇ 제34회 식품안전경영시스템 (KS Q ISO 22000:2018)
ㅇ 제6회 녹색경영시스템(KS I 7001:2018)
ㅇ 제17회 에너지경영시스템 (KS A ISO 50001:2018)</p>
<p class="md-p">분야별 진행되는 필기시험의 표준을 확인하시어 착오 없으시길 바랍니다.</p>
<p class="md-p">1. 응시 신청 접수
1) 접수 기간 : 2024. 11. 4(월) ~ 2024. 11. 15(금) 18:00</p>
<p class="md-p">2) 접수 방법 : 홈페이지 【자격시험신청】 으로 신청</p>
<p class="md-p">2. 필기시험 응시료
1) 응시료 : 99,000원 (부가세 포함)</p>
<p class="md-p">2) 입금처 : 기업은행 478-002057-01-041 (예금주) 한국심사자격인증원</p>
<p class="md-p">3) 연기/환불 신청</p>
<p class="md-p">ㅇ 신청 가능 기간 : 2024. 11. 18(월) ~ 2024. 11. 22(금) 18:00까지
ㅇ 신청 방법
(1) 본원 홈페이지 (www.kar.re.kr) &gt; 【공지사항】 &gt; (2024. 11. 29 시행)ISO 인증심사원 분야별 필기시험 유의사항 안내 &gt; [첨부] 시험 응시 연기 및 환불 신
100-2) 다운</p>
<p class="md-p">(2)  다운받은 신청서 작성하여 아래의 이메일 또는 팩스로 접수</p>
<p class="md-p">전화  02-2026-0153  팩스  02-2026-0155  이메일  kar0159@kar.re.kr</p>
<p class="md-p">주 시험 응시료는 환불 불가함. 단, 시험 시행 7일 전까지 연기/환불 신청한 경우에만 1회에 한하여 연기/환불 가능함.
[ 1]</p>
<p class="md-p">[주2] 금회 시험 이전의 시험응시 연기자는 인터넷으로 응시 신청을 하여야 함</p>
<p class="md-p">3. 세금계산서 발행 (KAR 홈페이지 &gt; 【영수증신청】으로 신청 요망)
1) 개인 : 성명/주소/주민등록번호</p>
<p class="md-p">2) 법인 : 사업자등록증 FAX 송부</p>
<p class="md-p">주 회계 담당 연락처
[ ]</p>
<p class="md-p">전화  02-2026-0157  팩스  02-2026-0155  이메일  kar0157@kar.re.kr</p>
<p class="md-p">4.  시험 장소 안내
시험장소는 가산디지털단지 부근에서 실시될 예정이며, 정확한 장소 공지는 시험시행일 7일 전에 우리원 홈페이지(www.kar.re.kr) &gt; 【공지사항】을 통해 안내되오니 참조하
바랍니다.</p>
<p class="md-p">[  필기시험 응시안내]</p>
<p class="md-p">1.  시험시간은 14:00~16:00(2시간)입니다.</p>
<p class="md-p">2.  시험 당일 13:30까지 고사장에 입실하여야 합니다.</p>
<p class="md-p">3.  시험장 주차비용은 응시생이 부담해야 하므로 가급적 대중교통을 이용하시기 바랍니다.</p>
<p class="md-p">4. 시험 준비물 및 유의사항
1) 응시자 지참물 : 개인 손목시계, 신분증(주민등록증/운전면허증/여권/공무원증)</p>
<p class="md-p">※ 신분증 미소지자 응시불가
2) 반드시 지정된 좌석에 착석</p>
<p class="md-p">3) 책상에 낙서 금지</p>
<p class="md-p">4) 휴대폰 사용 금지 (완전히 끌 것. 진동 사용 불가)</p>
<p class="md-p">5) 답안지 작성은 흑색 볼펜 또는 유성펜 등 지워지지 않는 검정색 필기구 사용 (연필 또는 샤프펜슬로 작성시 채점되지 않음)</p>
<p class="md-p">6) 답안 수정시 수정 테이프(수정액)를 사용하거나 두 줄로 횡선을 긋고, 새로운 답안을 작성하여 감독자의 날인을 받아야 함</p>
<p class="md-p">7) 시험문제 중에는 제시된 문항수를 선택하여 작성하는 선택형 문제가 있음</p>
<p class="md-p">※ 제시된 문항수 이상을 시험지에 기술하면 작성된 번호 순서대로 채점대상이 됨. 선택하지 않은 문제는 문제번호에 X를 크게 표시하고 “선택안함” 이라고 자필로 표기해야
8) 질문이 있는 경우는 거수. 다만 문제 자체에 대한 질문은 응답하지 않음</p>
<p class="md-p">9) KS 표준 낙서 금지 (회수되어 재사용 됨)</p>
<p class="md-p">10) 시험시행 후 60분 후부터 퇴실 가능하며, 퇴실 후 재입실 불가
11) 부정행위자는 우리원에서 주관하는 모든 시험에 3년 동안 응시 불가</p>
<p class="md-p">12) 시험 문제 및 답안지, 시험점수는 공개하지 않음</p>
<p class="md-p">13) 시험 결시의 경우, 시험 횟수 1회가 차감됨</p>
<p class="md-p">5. 합격자 발표
2024년 12월 13일(금) 10:00 개인별 문자 메세지 및 우리원 홈페이지【필기시험&gt;합격자 발표】를 통하여 합격자 결과 발표</p>
</div>
`,
