"content/notices/6449.html": `
<div class="md-body">
<p class="md-p">ISO 경영시스템인증심사원 분야별 필기시험(2025. 11. 28시행)장소 안내
ISO 경영시스템인증심사원 분야별 필기시험(2025. 11. 28시행)장소를 아래와 같이 안내합니다.
□분야별 필기시험 응시 내용
자격 분야  회차  표준
품질경영시스템(QMS, ISO 9001)  제158회  KS Q ISO 9001:2015
안전보건경영시스템(OHSMS, ISO 45001)  제95회  KS Q ISO 45001:2018
□시험일시: 2025년 11월 28일(금) 14:00 ~ 16:00 (2시간)
※당일 오후1시30분까지 시험장 입실 완료
□시험장소:가산BYC하이시티C동303호
-주소:서울특별시 금천구 가산디지털1로131
-교통편:지하철 가산디지털단지역1, 7호선7번 출구방향200미터
□응시자 명단
-제158회 품질경영시스템(QMS, ISO 9001)
연번  수험번호  성명
1  Q251101  김*재</p>
<p class="md-p">2  Q251102  김*현</p>
<p class="md-p">3  Q251103  정*빈</p>
<p class="md-p">4  Q251104  김*영</p>
<p class="md-p">5  Q251105  최*우</p>
<p class="md-p">6  Q251106  남*석</p>
<p class="md-p">7  Q251107  최*선</p>
<p class="md-p">8  Q251108  도*길</p>
<p class="md-p">9  Q251109  이*신</p>
<p class="md-p">10  Q251110  김*섭</p>
<p class="md-p">-제95회 안전보건경영시스템(OHSMS, ISO 45001)
연번  수험번호  성명
1  O251101  진*람</p>
<p class="md-p">□응시자 유의사항
1.답안 작성 관련 안내
ㅇ시험 유형B( 객관식) 필기시험
가. ‘검은색 사인펜’또는‘검은색 볼펜’으로OMR작성
나.모든 답안은 객관식이며1개의 정답만 정확히 칠함
다.답안 수정 시 수정 테이프를 사용하거나 답안지 교체 요청
라.답안지가 구겨지거나 오염되지 않도록 주의
2.주차 불가,대중교통수단 이용 요망
※본 건물 주차장 이용시,주차 요금은 개인 부담
3.응시자 지참물:개인 손목시계,신분증(주민등록증,운전면허증,여권,공무원증 등)
※신분증 미소지시 응시 불가
4.시험점수와 답안지는 미공개를 원칙으로 함
5.질문이 있는 경우는 거수(단,문제 자체에 대한 질문은 응답하지 않음)
6.배부된KS표준 낙서 금지(회수되어 재사용 됨)
7.시험시행 후60분 후부터 퇴실 가능하며,퇴실 후 재입실 불가
8.시험 결시시 시험횟수가1회 차감되며,차기 시험 신청 시 응시료를 납부하여야 함
9.시험 부정행위자는 우리원에서 주관하는 모든 시험에 3년간 시험을 응시 불가
□합격자 발표: 2025년 12월 12일(금) 10:00
-개인별 문자 메시지 및 우리원 홈페이지【필기시험&gt;합격자 발표】를 통하여 합격자 결과 발표</p>
</div>
`,
"content/notices/6461.html": `
<div class="md-body">
<p class="md-p">ISO 인증심사원 분야별 필기시험(2025. 12. 19 시행) 유의사항 안내</p>
<p class="md-p">다음 분야의 인증심사원 필기시험이 2025년 12월 19일 (금) 14:00에 실시됩니다.</p>
<p class="md-p">ㅇ 제159회 품질경영시스템 (KS Q ISO 9001:2015)
ㅇ 제110회 환경경영시스템 (KS I ISO 14001:2015)
ㅇ 제96회 안전보건경영시스템 (KS Q ISO 45001:2018)
ㅇ 제36회 식품안전경영시스템 (KS Q ISO 22000:2018)
ㅇ 제6회 녹색경영시스템(KS I 7001:2018)
ㅇ 제21회 에너지경영시스템 (KS A ISO 50001:2018)</p>
<p class="md-p">분야별 진행되는 필기시험의 표준을 확인하시어 착오 없으시길 바랍니다.</p>
<p class="md-p">1. 응시 신청 접수
1) 접수 기간 : 2025. 11. 24(월) ~ 2025. 12. 15(월) 18:00</p>
<p class="md-p">2) 접수 방법 : 홈페이지 【자격시험신청】 으로 신청</p>
<p class="md-p">2. 필기시험 응시료
1) 응시료 : 99,000원 (부가세 포함)</p>
<p class="md-p">2) 입금처 : 기업은행 478-002057-01-041 (예금주) 한국심사자격인증원</p>
<p class="md-p">3) 연기/환불 신청</p>
<p class="md-p">ㅇ 연기/환불 신청 가능 기간 : 2025. 12. 8(월) ~ 2025. 12. 12(금) 18:00까지
ㅇ 신청 방법
(1) 본원 홈페이지 (www.kar.re.kr) &gt; 【공지사항】 &gt; (2025. 12. 19 시행)ISO 인증심사원 분야별 필기시험 유의사항 안내 &gt; [첨부] 시험 응시 연기 및 환불 신
100-2) 다운</p>
<p class="md-p">(2)  다운받은 신청서 작성하여 아래의 이메일 또는 팩스로 접수</p>
<p class="md-p">전화  02-2026-0153  팩스  02-2026-0155  이메일  kar0159@kar.re.kr</p>
<p class="md-p">주 시험 응시료는 환불 불가함. 단, 시험 시행 7일 전까지 연기/환불 신청한 경우에만 1회에 한하여 연기/환불 가능함.
[ 1]</p>
<p class="md-p">[주2] 금회 시험 이전의 시험응시 연기자는 인터넷으로 응시 신청을 하여야 함</p>
<p class="md-p">3. 세금계산서 발행 (KAR 홈페이지 &gt; 【영수증신청】으로 신청 요망)
1) 개인 : 성명/주소/주민등록번호</p>
<p class="md-p">2) 법인 : 사업자등록증 FAX 송부</p>
<p class="md-p">주 회계 담당 연락처
[ ]</p>
<p class="md-p">전화  02-2026-0157  팩스  02-2026-0155  이메일  kar0157@kar.re.kr</p>
<p class="md-p">4.  시험 장소 안내
시험장소는 가산디지털단지 부근에서 실시될 예정이며, 정확한 장소 공지는 시험시행일 7일 전에 우리원 홈페이지(www.kar.re.kr) &gt; 【공지사항】을 통해 안내되오니 참조하
바랍니다.</p>
<p class="md-p">[  필기시험 응시안내]</p>
<p class="md-p">1.  시험시간은 14:00~16:00(2시간)입니다.</p>
<p class="md-p">2.  시험 당일 13:30까지 고사장에 입실하여야 합니다.</p>
<p class="md-p">3.  시험장 주차비용은 응시생이 부담해야 하므로 가급적 대중교통을 이용하시기 바랍니다.</p>
<p class="md-p">4. 시험 준비물 및 유의사항
1) 응시자 지참물 : 개인 손목시계, 신분증(주민등록증/운전면허증/여권/공무원증)</p>
<p class="md-p">※ 신분증 미소지자 응시불가
2) 반드시 지정된 좌석에 착석</p>
<p class="md-p">3) 책상에 낙서 금지</p>
<p class="md-p">4) 휴대폰 사용 금지 (완전히 끌 것. 진동 사용 불가)</p>
<p class="md-p">5) 질문이 있는 경우는 거수. 다만 문제 자체에 대한 질문은 응답하지 않음</p>
<p class="md-p">6) KS 표준 낙서 금지 (회수되어 재사용 됨)</p>
<p class="md-p">7) 시험시행 후 60분 후부터 퇴실 가능하며, 퇴실 후 재입실 불가</p>
<p class="md-p">8) 부정행위자는 우리원에서 주관하는 모든 시험에 3년 동안 응시 불가</p>
<p class="md-p">9) 시험 문제 및 답안지, 시험점수는 공개하지 않음</p>
<p class="md-p">10) 시험 결시의 경우, 시험 횟수 1회가 차감됨</p>
<p class="md-p">5. 답안 작성 관련 안내
ㅇ 시험 유형B (객관식) 필기시험
가. 검은색 사인펜 또는 검은색 볼펜으로 OMR 작성
나. 모든 답안은 객관식이며 1개의 정답만 정확히 칠함
다. 답안 수정 시 수정 테이프를 사용하거나 답안지 교체 요청
라. 답안지가 구겨지거나 오염되지 않도록 주의</p>
<p class="md-p">5. 합격자 발표
2026년 1월 2일(금) 10:00 개인별 문자 메세지 및 우리원 홈페이지【필기시험&gt;합격자 발표】를 통하여 합격자 결과 발표</p>
</div>
`,
