<p class="md-p">2. 본원(KAR)은 디지털 전환(DX) 환경에서 인증심사원이 IT 기반 경영시스 템을 효과적으로 이해하고 심사할 수 있도록 「IT 활용 경영시스템 심사 실무」 교육 과정
같이 개최하고자 합니다.</p>
